  if (toks.length && L.QUANTITY_BEFORE.has(lastOf(toks))) return true;
  const nxt = NEXT_LOW_WORD_RE.exec(after);
  return !!nxt && cueWord(nxt[1], L.QUANTITY_AFTER);
