  text = text.replace(rx(`(?<=[${W}])[’‘\`\xb4ʼ′](?=[${W}])`), "'");
  text = text.replace(/[“”„\xab\xbb]/g, '"');
  text = text.replace(/[’‘]/g, "'");
  text = text.replaceAll("…", "...");
  // en/em dash between numbers -> hyphen (ranges); elsewhere a pause
  text = text.replace(/(?<=\d)\s?[–—]\s?(?=\d)/gu, "-");
  text = text.replace(/\s[–—]\s/gu, ", ");
