/**
 * Written forms of a FOREIGN_NAMES key: as written, ALL CAPS, and unless exact-case also lower/Capitalized. An
 * exact-case key gets no Turkish ALL CAPS form either: "GEMİNİ" is the Turkish word "gemini" in capitals.
 */
function nameForms(key) {
  if (L.FOREIGN_NAMES_EXACT_CASE.has(key)) return [key, key.toUpperCase()];
  const low = key.toLowerCase();
  // ALL CAPS (Latin and Turkish: "INSTAGRAM", "İNSTAGRAM"), youtube, Youtube, İnstagram
  return [
    key,
    key.toUpperCase(),
    trUpper(key),
    low,
    low.slice(0, 1).toUpperCase() + low.slice(1),
    trUpper(low.slice(0, 1)) + low.slice(1),
  ];
}

function buildNames() {
  const table = new Map ();
  for (const [key, spoken] of Object.entries(L.FOREIGN_NAMES))
    for (const form of nameForms(key)) if (!table.has(form)) table.set(form, spoken);
  for (const [key, spoken] of Object.entries(L.FOREIGN_NAMES)) table.set(key, spoken); // an exact key beats another key's generated form
  const alt = byLength(table.keys()).map(escapeRe).join("|");
  // not inside a word, URL, e-mail address or handle ("google.com", "@google", "/google"); an optional
  // apostrophe suffix ("Google'da"), then a word end
  const re = rx(`(?<![${W}@./:\\\\])(?<![${W}]')(${alt})(?:'([${LET}]+))?(?![${W}@+]|'[${LET}]|[./:][${W}])`);
  return [table, re];
}

const [NAMES, NAMES_RE] = buildNames();

/**
 * Brands and loanwords to their Turkish pronunciation: "iPhone'umdan" -> "ayfonumdan", "Google'da" -> "Gugılda". A
 * Capitalized name stays capitalized (Turkish rules: "Instagram" -> "İnstagram", never a dotless ı); ALL-CAPS and
 * lowercase ones come out lowercase, like spelled acronyms.
 */
function passNames(text) {
  return sub(
    NAMES_RE,
    (m) => {
      const written = m[1];
      const spoken = suffix(NAMES.get(written) , m[2]);
      return isUpper(written[0]) && !isAllCaps(written) ? trCapitalize(spoken) : spoken;
    },
    text,
  );
}

const URL_RE = rx(
  `${B}(?:https?://)?(?:www\\.)?[${W}-]+(?:\\.[${W}-]+)*\\.(?:com|net|org|gov|edu|io|ai|tr|co|info|biz|me|app|dev)(?:\\.[a-z]{2})?(?:/[^\\s]*)?`,
  "i",
);
const EMAIL_RE = rx(`${B}[${W}.+-]+@[${W}-]+(?:\\.[${W}-]+)+${B}`);

const TLD = {
  com: "kom",
  tr: "te re",
  net: "net",
  org: "org",
  gov: "gov",
  edu: "edu",
  io: "ay o",
  ai: "ey ay",
};

function readWebToken(tok) {
  const parts = [];
  for (const piece of tok.split(/([./@_-])/)) {
    if (!piece) continue;
    if (piece === ".") parts.push("nokta");
    else if (piece === "/") parts.push("eğik çizgi");
    else if (piece === "@") parts.push("et");
    else if (piece === "_") parts.push("alt çizgi");
    else if (piece === "-") parts.push("tire");
    else if (piece.toLowerCase() === "www") parts.push("ve ve ve");
    else if (Object.hasOwn(TLD, piece.toLowerCase())) parts.push(TLD[piece.toLowerCase()]);
    else if (isDigits(piece)) parts.push(piece.length <= 4 ? readDigitGroup(piece) : digitsToWords(piece));
    else parts.push(trLower(piece));
  }
  return parts.join(" ");
}

function passWeb(text) {
  text = sub(EMAIL_RE, (m) => readWebToken(m[0]), text);
  return sub(URL_RE, (m) => readWebToken(m[0].replace(/^https?:\/\//i, "").replace(/\/+$/, "")), text);
}

const ABBR_RE = rx(`(?<![${W}.])(${byLength(Object.keys(L.ABBREVIATIONS)).map(escapeRe).join("|")})(?=[\\s,;:!?)"']|$)`);
const PAGE_RE = rx(`(?<![${W}.])([sc])\\.\\s?(?=\\d)`);
const SENTENCE_NEXT_RE = new RegExp(`^\\s+[${UP}]`, "u");
